    if isinstance(value, str):
        return value
    try:
        return json.dumps(value, ensure_ascii=False)
    except Exception:
        return str(value)

def truncate_text(value: str, limit: int) -> str:
    if len(value) <= limit:
        return value
    return value[:limit]

def cleanup_sessions() -> None:
    cutoff = now_ts() - SESSION_TTL_SECONDS
    with sessions_lock:
        expired = []
        for sid, messages in sessions.items():
            if not messages:
                expired.append(sid)
                continue
            latest = 0
            for msg in messages:
                ts = int(msg.get("ts", 0) or 0)
                if ts > latest:
                    latest = ts
            if latest < cutoff:
                expired.append(sid)
        for sid in expired:
            sessions.pop(sid, None)

def get_session_messages(session_id: str) -> list[dict[str, Any]]:
    with sessions_lock:
        if session_id not in sessions:
            sessions[session_id] = []
        return list(sessions[session_id])

def append_to_session(session_id: str, role: str, content: str) -> None:
    content = normalize_text(content)
    with sessions_lock:
        if session_id not in sessions:
            sessions[session_id] = []
        sessions[session_id].append({
            "role": role,
            "content": content,
            "ts": now_ts(),
        })
        if len(sessions[session_id]) > MAX_MESSAGES_PER_SESSION:
            sessions[session_id] = sessions[session_id][-MAX_MESSAGES_PER_SESSION:]

def delete_session(session_id: str) -> None:
    with sessions_lock:
        sessions.pop(session_id, None)

def build_preview(content: str) -> str:
    if not content:
        return "Chat"
    text = content.replace("\r", " ").replace("\n", " ").strip()
    if "[VISION CONTEXT" in text:
        text = text.split("[VISION CONTEXT", 1)[0].strip() or "Képes üzenet"
    return text[:80] if text else "Chat"

def build_cerebras_messages(history: list[dict[str, Any]]) -> list[dict[str, str]]:
    selected: list[dict[str, str]] = []
    total_chars = 0
    count = 0
    for msg in reversed(history):
        role = msg.get("role")
        if role not in {"user", "assistant"}:
            continue
        content = normalize_text(msg.get("content", ""))
        if not content:
            continue
        if count == 0 and len(content) > MAX_HISTORY_CHARS:
            content = content[-MAX_HISTORY_CHARS:]
        next_size = len(content)
        if count > 0 and total_chars + next_size > MAX_HISTORY_CHARS:
            break
        selected.append({"role": role, "content": content})
        total_chars += next_size
        count += 1
        if count >= MAX_MESSAGES_FOR_MODEL:
            break
    selected.reverse()
    if CEREBRAS_SYSTEM_PROMPT.strip():
        return [{"role": "system", "content": CEREBRAS_SYSTEM_PROMPT}] + selected
    return selected

def safe_json_loads(text: str) -> Any:
    return json.loads(text)

def strip_code_fences(text: str) -> str:
    value = text.strip()
    if value.startswith("```"):
        lines = value.splitlines()
        if lines:
            if lines.startswith("```"):
                lines = lines[1:]
            if lines and lines[-1].strip() == "```":
                lines = lines[:-1]
            value = "\n".join(lines).strip()
    return value

def coerce_json_text(text: str) -> str:
    raw = strip_code_fences(text)
    if not raw:
        return json.dumps({
            "summary": "",
            "visible_text": [],
            "objects": [],
            "details": [],
            "imaging": {
                "lighting": "",
                "camera_artifacts": [],
                "color_and_materials": [],
                "spatial_layout": "",
            },
        }, ensure_ascii=False)
    try:
        parsed = safe_json_loads(raw)
        return json.dumps(parsed, ensure_ascii=False)
    except Exception:
        return json.dumps({
            "summary": "",
            "visible_text": [],
            "objects": [],
            "details": [raw],
            "imaging": {
                "lighting": "",
                "camera_artifacts": [],
                "color_and_materials": [],
                "spatial_layout": "",
            },
        }, ensure_ascii=False)

def extract_data_url_payload(value: str) -> str:
    if "," in value and value.lstrip().startswith("data:"):
        return value.split(",", 1)[12]
    return value

def normalize_mime_type(value: Any) -> str:
    mime = normalize_text(value).strip().lower()
    if mime == "image/jpg":
        mime = "image/jpeg"
    return mime

def decode_base64_image(data: str) -> bytes:
    payload = extract_data_url_payload(data).strip()
    if not payload:
        raise ValueError("Hiányzó kép adat")
    try:
        return base64.b64decode(payload, validate=True)
    except binascii.Error:
        try:
            return base64.b64decode(payload + "=" * ((4 - len(payload) % 4) % 4), validate=False)
        except Exception as exc:
            raise ValueError("Érvénytelen base64 kép adat") from exc
    except Exception as exc:
        raise ValueError("Érvénytelen base64 kép adat") from exc

def validate_and_prepare_images(images: Any) -> list[dict[str, Any]]:
    if images is None:
        return []
    if not isinstance(images, list):
        raise ValueError("Az images mezőnek listának kell lennie")
    if len(images) > MAX_IMAGES:
        raise ValueError(f"Túl sok kép. Maximum: {MAX_IMAGES}")
    prepared: list[dict[str, Any]] = []
    total_bytes = 0
    for item in images:
        if not isinstance(item, dict):
            raise ValueError("Minden kép objektum kell legyen")
        media_type = normalize_mime_type(item.get("media_type", ""))
        data = normalize_text(item.get("data", ""))
        if media_type not in ALLOWED_IMAGE_MIME_TYPES:
            raise ValueError(f"Nem támogatott kép MIME típus: {media_type}")
        raw_bytes = decode_base64_image(data)
        if not raw_bytes:
            raise ValueError("Üres kép adat")
        if len(raw_bytes) > MAX_SINGLE_IMAGE_BYTES:
            raise ValueError(f"Egy kép túl nagy. Maximum: {MAX_SINGLE_IMAGE_BYTES} bájt")
        total_bytes += len(raw_bytes)
        if total_bytes > MAX_TOTAL_IMAGE_BYTES:
            raise ValueError(f"Az összes kép túl nagy. Maximum: {MAX_TOTAL_IMAGE_BYTES} bájt")
        prepared.append({
            "media_type": media_type,
            "raw_bytes": raw_bytes,
        })
    return prepared

def extract_gemini_text(response: Any) -> str:
    text = getattr(response, "text", None)
    if isinstance(text, str) and text.strip():
        return text
    candidates = getattr(response, "candidates", None)
    if not candidates:
        return ""
    chunks: list[str] = []
    for candidate in candidates:
        content = getattr(candidate, "content", None)
        if not content:
            continue
        parts = getattr(content, "parts", None) or []
        for part in parts:
            part_text = getattr(part, "text", None)
            if part_text:
                chunks.append(part_text)
    return "".join(chunks)

def analyze_images_with_gemini(images: list[dict[str, Any]], user_text: str) -> str:
    api_key = require_env("GEMINI_API_KEY")
    client = genai.Client(api_key=api_key)
    parts: list[Any] = []
    for image in images:
        parts.append(
            types.Part(
                inline_data=types.Blob(
                    mime_type=image["media_type"],
                    data=image["raw_bytes"],
                )
            )
        )
    if user_text.strip():
        parts.append(types.Part.from_text(text=user_text.strip()))
    else:
        parts.append(types.Part.from_text(text="Analyze this image in full detail and return strictly valid JSON."))
    response = client.models.generate_content(
        model=GEMINI_MODEL,
        contents=[types.Content(role="user", parts=parts)],
        config=types.GenerateContentConfig(
            max_output_tokens=GEMINI_MAX_OUTPUT_TOKENS,
            thinking_config=types.ThinkingConfig(thinking_level="HIGH"),
            media_resolution=types.MediaResolution.MEDIA_RESOLUTION_HIGH,
            response_mime_type="application/json",
            system_instruction=[types.Part.from_text(text=GEMINI_VISION_SYSTEM)],
        ),
    )
    return coerce_json_text(extract_gemini_text(response))

def sse_payload(obj: dict[str, Any]) -> str:
    return "data: " + json.dumps(obj, ensure_ascii=False) + "\n\n"

def normalize_cerebras_delta_content(value: Any) -> str:
    if value is None:
        return ""
    if isinstance(value, str):
        return value
    if isinstance(value, list):
        parts: list[str] = []
        for item in value:
            if isinstance(item, str):
                parts.append(item)
            elif isinstance(item, dict):
                text = item.get("text")
                if isinstance(text, str):
                    parts.append(text)
            else:
                text = getattr(item, "text", None)
                if isinstance(text, str):
                    parts.append(text)
                else:
                    parts.append(str(item))
        return "".join(parts)
    if isinstance(value, dict):
        text = value.get("text")
        if isinstance(text, str):
            return text
        return json.dumps(value, ensure_ascii=False)
    text = getattr(value, "text", None)
    if isinstance(text, str):
        return text
    return str(value)

def get_cerebras_client() -> Cerebras:
    api_key = require_env("CEREBRAS_API_KEY")
    return Cerebras(api_key=api_key)

