@app.route("/api/chat", methods=["POST"])
def chat() -> Response:
    cleanup_sessions()
    try:
        data = request.get_json(force=False, silent=False)
    except BadRequest:
        return jsonify({"error": "Érvénytelen JSON kérés"}), 400
    if not isinstance(data, dict):
        return jsonify({"error": "A kérés törzsének JSON objektumnak kell lennie"}), 400

    raw_message = normalize_text(data.get("message", ""))
    raw_message = truncate_text(raw_message, MAX_MESSAGE_CHARS)
    incoming_session_id = normalize_text(data.get("session_id", "")).strip()
    session_id = incoming_session_id or str(uuid.uuid4())

    try:
        images = validate_and_prepare_images(data.get("images", []))
    except ValueError as exc:
        return jsonify({"error": str(exc)}), 400

    if not raw_message and not images:
        return jsonify({"error": "Üres kérés"}), 400

    def generate():
        yield sse_payload({"type": "session", "session_id": session_id})
        full_user_message = raw_message
        if images:
            try:
                image_json = analyze_images_with_gemini(images, raw_message)
                vision_block = "\n\n[VISION CONTEXT — Gemini image analysis JSON]\n" + image_json + "\n[END VISION CONTEXT]"
                full_user_message = (raw_message + vision_block).strip() if raw_message else vision_block
            except Exception as exc:
                yield sse_payload({"type": "warning", "message": "Kép elemzés sikertelen: " + normalize_text(exc)})
        append_to_session(session_id, "user", full_user_message)
        history = get_session_messages(session_id)
        cerebras_messages = build_cerebras_messages(history)
        if not cerebras_messages:
            yield sse_payload({"type": "error", "message": "Nincs elküldhető üzenet"})
            yield sse_payload({"type": "done"})
            return
        full_response = ""
        try:
            client = get_cerebras_client()
            stream = client.chat.completions.create(
                messages=cerebras_messages,
                model=CEREBRAS_MODEL,
                stream=True,
                max_completion_tokens=CEREBRAS_MAX_COMPLETION_TOKENS,
                temperature=CEREBRAS_TEMPERATURE,
            )
            for chunk in stream:
                choices = getattr(chunk, "choices", None) or []
                if not choices:
                    continue
                first_choice = choices
                delta = getattr(first_choice, "delta", None)
                delta_content = normalize_cerebras_delta_content(getattr(delta, "content", None))
                if delta_content:
                    full_response += delta_content
                    yield sse_payload({"type": "content", "text": delta_content})
            append_to_session(session_id, "assistant", full_response)
        except Exception as exc:
            yield sse_payload({"type": "error", "message": normalize_text(exc)})
        yield sse_payload({"type": "done"})

    headers = {
        "Cache-Control": "no-cache, no-transform",
        "Connection": "keep-alive",
        "X-Accel-Buffering": "no",
    }
    return Response(stream_with_context(generate()), mimetype="text/event-stream", headers=headers)

@app.route("/api/sessions", methods=["GET"])
def get_sessions() -> Response:
    cleanup_sessions()
    result: list[dict[str, Any]] = []
    with sessions_lock:
        for sid, messages in sessions.items():
            if not messages:
                continue
            preview = "Chat"
            for msg in messages:
                if msg.get("role") == "user":
                    preview = build_preview(normalize_text(msg.get("content", "")))
                    break
            updated_at = 0
            for msg in messages:
                ts = int(msg.get("ts", 0) or 0)
                if ts > updated_at:
                    updated_at = ts
            result.append({
                "session_id": sid,
                "preview": preview,
                "count": len(messages),
                "updated_at": updated_at,
            })
    result.sort(key=lambda item: item["updated_at"], reverse=True)
    return jsonify({"sessions": result})

